a1=A.aw(0,"L1-21",1,A.a([A.f("Price breaks support/resistance then reverses immediately, without continuing","Gi\xe1 ph\xe1 v\u1ee1 h\u1ed7 tr\u1ee3/kh\xe1ng c\u1ef1 r\u1ed3i quay \u0111\u1ea7u ngay, kh\xf4ng \u0111i ti\u1ebfp","\u4ef7\u683c\u7a81\u7834\u652f\u6491/\u963b\u529b\u540e\u7acb\u5373\u53cd\u8f6c\uff0c\u672a\u80fd\u7ee7\u7eed","\u4fa1\u683c\u304c\u30b5\u30dd\u30fc\u30c8/\u30ec\u30b8\u30b9\u30bf\u30f3\u30b9\u3092\u7a81\u7834\u3057\u305f\u5f8c\u3001\u7d99\u7d9a\u305b\u305a\u3059\u3050\u306b\u623b\u308b\u3053\u3068","\uac00\uaca9\uc774 \uc9c0\uc9c0/\uc800\ud56d\uc744 \ub3cc\ud30c\ud55c \ud6c4 \uc774\uc5b4\uac00\uc9c0 \ubabb\ud558\uace0 \ubc14\ub85c \ub418\ub3cc\uc544\uac00\ub294 \uac83"),A.f("Price breaks out and always continues forever","Gi\xe1 ph\xe1 v\u1ee1 v\xe0 lu\xf4n \u0111i ti\u1ebfp m\xe3i m\xe3i","\u4ef7\u683c\u7a81\u7834\u540e\u603b\u662f\u6c38\u8fdc\u5ef6\u7eed","\u4fa1\u683c\u304c\u7a81\u7834\u5f8c\u5e38\u306b\u7d99\u7d9a\u3059\u308b\u3053\u3068","\uac00\uaca9\uc774 \ub3cc\ud30c \ud6c4 \ud56d\uc0c1 \uacc4\uc18d \uc774\uc5b4\uac00\ub294 \uac83"),A.f("A special type of order","M\u1ed9t lo\u1ea1i l\u1ec7nh \u0111\u1eb7c bi\u1ec7t","\u4e00\u79cd\u7279\u6b8a\u8ba2\u5355\u7c7b\u578b","\u7279\u5225\u306a\u7a2e\u985e\u306e\u6ce8\u6587","\ud2b9\ubcc4\ud55c \uc885\ub958\uc758 \uc8fc\ubb38"),A.f("Only happens on Spot","Ch\u1ec9 x\u1ea3y ra tr\xean Spot","\u53ea\u53d1\u751f\u5728\u73b0\u8d27\u4ea4\u6613\u4e2d","\u73fe\u7269\u53d6\u5f15\u3067\u306e\u307f\u767a\u751f\u3059\u308b","\ud604\ubb3c\uc5d0\uc11c\ub9cc \ubc1c\uc0dd\ud568")],f8),a2,a1)
