a3=A.f("What does ATR (Average True Range) measure?","ATR (Average True Range) \u0111o \u0111i\u1ec1u g\xec?","ATR\uff08\u5e73\u5747\u771f\u5b9e\u6ce2\u5e45\uff09\u8861\u91cf\u4ec0\u4e48\uff1f","ATR\uff08\u5e73\u5747\u771f\u306e\u5024\u5e45\uff09\u306f\u4f55\u3092\u6e2c\u5b9a\u3057\u307e\u3059\u304b\uff1f","ATR(\ud3c9\uade0 \uc2e4\uccb4 \ubc94\uc704)\ub294 \ubb34\uc5c7\uc744 \uce21\uc815\ud558\ub098\uc694?")
a2=A.aw(0,"L1-22",1,A.a([A.f("Average price volatility","M\u1ee9c \u0111\u1ed9 bi\u1ebfn \u0111\u1ed9ng gi\xe1 trung b\xecnh","\u5e73\u5747\u4ef7\u683c\u6ce2\u52a8\u5e45\u5ea6","\u5e73\u5747\u7684\u306a\u4fa1\u683c\u5909\u52d5\u5e45","\ud3c9\uade0 \uac00\uaca9 \ubcc0\ub3d9\uc131"),A.f("Average volume","Kh\u1ed1i l\u01b0\u1ee3ng trung b\xecnh","\u5e73\u5747\u6210\u4ea4\u91cf","\u5e73\u5747\u51fa\u6765\u9ad8","\ud3c9\uade0 \uac70\ub798\ub7c9"),A.f("Number of open positions","S\u1ed1 l\u1ec7nh \u0111ang m\u1edf","\u6301\u4ed3\u6570\u91cf","\u4fdd\u6709\u30dd\u30b8\u30b7\u30e7\u30f3\u6570","\ubcf4\uc720 \uc911\uc778 \ud3ec\uc9c0\uc158 \uc218"),A.f("Exchange fee rate","T\u1ec9 l\u1ec7 ph\xed s\xe0n","\u4ea4\u6613\u6240\u8d39\u7387","\u53d6\u5f15\u6240\u306e\u624b\u6570\u6599\u7387","\uac70\ub798\uc18c \uc218\uc218\ub8cc\uc728")],f8),a3,a2)
