a1=A.aw(0,"L2-21",2,A.a([A.f("Fairly high correlation, a sharp BTC drop usually drags altcoins down too","T\u01b0\u01a1ng quan kh\xe1 cao, BTC gi\u1ea3m m\u1ea1nh th\u01b0\u1eddng k\xe9o theo altcoin gi\u1ea3m","\u76f8\u5173\u6027\u76f8\u5f53\u9ad8\uff0cBTC\u5927\u8dcc\u901a\u5e38\u4f1a\u62d6\u7d2f\u5c71\u5be8\u5e01\u4e0b\u8dcc","\u304b\u306a\u308a\u9ad8\u3044\u76f8\u95a2\u304c\u3042\u308a\u3001BTC\u6025\u843d\u6642\u30a2\u30eb\u30c8\u30b3\u30a4\u30f3\u3082\u5927\u62b5\u4e00\u7dd2\u306b\u4e0b\u843d\u3059\u308b","\uc0c1\ub2f9\ud788 \ub192\uc740 \uc0c1\uad00\uad00\uacc4\uac00 \uc788\uc5b4 BTC \uae09\ub77d \uc2dc \uc54c\ud2b8\ucf54\uc778\ub3c4 \ub300\uac1c \ud568\uaed8 \ud558\ub77d\ud568"),A.f("Completely unrelated","Ho\xe0n to\xe0n kh\xf4ng li\xean quan","\u5b8c\u5168\u65e0\u5173","\u5168\u304f\u95a2\u4fc2\u306a\u3044","\uc804\ud600 \uad00\ub828 \uc5c6\uc74c"),A.f("Always moves opposite to BTC","Lu\xf4n \u0111i ng\u01b0\u1ee3c chi\u1ec1u BTC","\u603b\u662f\u4e0eBTC\u53cd\u5411\u8fd0\u884c","\u5e38\u306bBTC\u3068\u9006\u65b9\u5411\u306b\u52d5\u304f","\ud56d\uc0c1 BTC\uc640 \ubc18\ub300\ub85c \uc6c0\uc9c1\uc784"),A.f("Only correlated on weekends","Ch\u1ec9 t\u01b0\u01a1ng quan v\xe0o cu\u1ed1i tu\u1ea7n","\u53ea\u5728\u5468\u672b\u76f8\u5173","\u9031\u672b\u3060\u3051\u76f8\u95a2\u304c\u3042\u308b","\uc8fc\ub9d0\uc5d0\ub9cc \uc0c1\uad00\uad00\uacc4\uac00 \uc788\uc74c")],f9),a2,a1)
