m=A.aw(0,"L4-07",4,A.a([A.f("Calculating the optimal fraction of capital to risk per trade based on win rate and expected R:R","T\xednh t\u1ec9 l\u1ec7 v\u1ed1n t\u1ed1i \u01b0u n\xean \u0111\u1eb7t c\u01b0\u1ee3c m\u1ed7i l\u1ec7nh d\u1ef1a tr\xean t\u1ec9 l\u1ec7 th\u1eafng v\xe0 R:R k\u1ef3 v\u1ecdng","\u6839\u636e\u80dc\u7387\u548c\u671f\u671b\u76c8\u4e8f\u6bd4\u8ba1\u7b97\u6bcf\u7b14\u4ea4\u6613\u5e94\u627f\u62c5\u7684\u6700\u4f18\u8d44\u91d1\u6bd4\u4f8b","\u52dd\u7387\u3068\u671f\u5f85R:R\u306b\u57fa\u3065\u304d1\u30c8\u30ec\u30fc\u30c9\u3042\u305f\u308a\u306b\u30ea\u30b9\u30af\u306b\u6652\u3059\u3079\u304d\u6700\u9069\u306a\u8cc7\u672c\u6bd4\u7387\u3092\u8a08\u7b97\u3059\u308b\u305f\u3081","\uc2b9\ub960\uacfc \uae30\ub300 R:R\uc744 \ubc14\ud0d5\uc73c\ub85c \uac70\ub798\ub2f9 \ub9ac\uc2a4\ud06c\uc5d0 \uac78\uc5b4\uc57c \ud560 \ucd5c\uc801 \uc790\ubcf8 \ube44\uc728\uc744 \uacc4\uc0b0\ud558\uae30 \uc704\ud574"),A.f("Calculating optimal trading fees","T\xednh ph\xed giao d\u1ecbch t\u1ed1i \u01b0u","\u8ba1\u7b97\u6700\u4f18\u4ea4\u6613\u624b\u7eed\u8d39","\u6700\u9069\u306a\u53d6\u5f15\u624b\u6570\u6599\u3092\u8a08\u7b97\u3059\u308b\u305f\u3081","\ucd5c\uc801 \uac70\ub798 \uc218\uc218\ub8cc\ub97c \uacc4\uc0b0\ud558\uae30 \uc704\ud574"),A.f("Predicting market news","D\u1ef1 \u0111o\xe1n tin t\u1ee9c th\u1ecb tr\u01b0\u1eddng","\u9884\u6d4b\u5e02\u573a\u65b0\u95fb","\u5e02\u5834\u30cb\u30e5\u30fc\u30b9\u3092\u4e88\u6e2c\u3059\u308b\u305f\u3081","\uc2dc\uc7a5 \ub274\uc2a4\ub97c \uc608\uce21\ud558\uae30 \uc704\ud574"),A.f("Determining the best trading timeframe","X\xe1c \u0111\u1ecbnh khung th\u1eddi gian giao d\u1ecbch t\u1ed1t nh\u1ea5t","\u786e\u5b9a\u6700\u4f73\u4ea4\u6613\u5468\u671f","\u6700\u9069\u306a\u53d6\u5f15\u6642\u9593\u8db3\u3092\u6c7a\u3081\u308b\u305f\u3081","\ucd5c\uc801 \uac70\ub798 \uc2dc\uac04\ub300\ub97c \uc815\ud558\uae30 \uc704\ud574")],e1),l,m)
